                  data-testid="save-status"
                  aria-live="polite"
                  className={saveStatus === 'error' ? 'text-red-600' : ''}
                >
                  {saveStatus === 'saving' ? 'Saving…' : saveStatus === 'error' ? 'Not saved — storage full' : (
