@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

@layer components {
  .icon-btn {
    @apply inline-grid size-8 shrink-0 place-items-center rounded-md text-zinc-500 hover:bg-zinc-200 hover:text-zinc-900 focus-visible:outline-2 focus-visible:outline-indigo-500 dark:text-zinc-400 dark:hover:bg-zinc-800 dark:hover:text-zinc-100;
  }
  .pane-label {
    @apply px-4 pt-2 text-[11px] font-semibold tracking-wider text-zinc-400 uppercase dark:text-zinc-500;
  }
}

.md-preview {
  line-height: 1.65;
  overflow-wrap: anywhere;
}
.md-preview > * + * { margin-top: 0.75em; }
.md-preview h1 { font-size: 1.75rem; font-weight: 700; line-height: 1.25; }
.md-preview h2 { font-size: 1.375rem; font-weight: 700; line-height: 1.3; margin-top: 1.25em; }
.md-preview h3 { font-size: 1.15rem; font-weight: 600; margin-top: 1.1em; }
.md-preview h4, .md-preview h5, .md-preview h6 { font-weight: 600; margin-top: 1em; }
.md-preview a { color: var(--color-indigo-600); text-decoration: underline; text-underline-offset: 2px; }
.dark .md-preview a { color: var(--color-indigo-400); }
.md-preview ul { list-style: disc; padding-left: 1.5rem; }
.md-preview ol { list-style: decimal; padding-left: 1.5rem; }
.md-preview li > ul, .md-preview li > ol { margin-top: 0.25em; }
.md-preview ul.task-list { list-style: none; padding-left: 0.25rem; }
.md-preview li.task-item ul.task-list { padding-left: 1.5rem; }
.md-preview li.task-item > label { display: inline-flex; align-items: baseline; gap: 0.5rem; cursor: pointer; }
.md-preview li.task-item input { accent-color: var(--color-indigo-600); width: 1rem; height: 1rem; transform: translateY(2px); cursor: pointer; }
.md-preview li.task-item.done > label > span { color: var(--color-zinc-500); text-decoration: line-through; }
.md-preview code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.875em;
  background: var(--color-zinc-100);
  border-radius: 4px;
  padding: 0.1em 0.35em;
}
.dark .md-preview code { background: var(--color-zinc-800); }
.md-preview pre {
  background: var(--color-zinc-100);
  border-radius: 6px;
  padding: 0.75rem 1rem;
  overflow-x: auto;
}
.dark .md-preview pre { background: var(--color-zinc-900); }
.md-preview pre code { background: none; padding: 0; font-size: 0.85rem; }
.md-preview blockquote {
  border-left: 3px solid var(--color-zinc-300);
  padding-left: 1rem;
  color: var(--color-zinc-600);
}
.dark .md-preview blockquote { border-color: var(--color-zinc-700); color: var(--color-zinc-400); }
.md-preview hr { border-color: var(--color-zinc-200); }
.dark .md-preview hr { border-color: var(--color-zinc-800); }

