                onClick={() => updateNote(active.id, { pinned: !active.pinned }, false)}
                className={`icon-btn ${active.pinned ? 'text-indigo-600 dark:text-indigo-400' : ''}`}
                aria-label={active.pinned ? 'Unpin note' : 'Pin note'}
                aria-pressed={active.pinned}
                title={active.pinned ? 'Unpin' : 'Pin to top'}
              >
                <Icon name={active.pinned ? 'pin-filled' : 'pin'} />
              </button>
              <button
                type="button"
                onClick={() => setPendingDelete(active)}
                className="icon-btn hover:text-red-600 dark:hover:text-red-400"
                aria-label="Delete note"
                title="Delete"
              >
                <Icon name="trash" />
              </button>
              <div className="flex w-full items-center gap-3 px-1 text-xs text-zinc-500 md:w-auto md:order-none dark:text-zinc-400">
                <span data-testid="word-count">
                  {words} {words === 1 ? 'word' : 'words'}
                </span>
                <span
                  data-testid="save-status"
                  aria-live="polite"
                  className={saveStatus === 'error' ? 'text-red-600' : ''}
                >
                  {saveStatus === 'saving' ? 'Saving…' : saveStatus === 'error' ? 'Not saved — storage full' : (
                    <span className="inline-flex items-center gap-1">
                      <Icon name="check" className="size-3.5 text-emerald-600 dark:text-emerald-400" />
                      Saved
                    </span>
                  )}
                </span>
              </div>
            </header>
            <div className="flex min-h-0 flex-1 flex-col overflow-y-auto md:grid md:grid-cols-2 md:overflow-hidden">
              <section className="flex flex-col border-zinc-200 md:min-h-0 md:border-r dark:border-zinc-800" aria-label="Markdown source">
                <div className="pane-label">Markdown</div>
                <textarea
                  id="editor"
                  value={active.content}
                  onChange={(e) => updateNote(active.id, { content: e.target.value })}
                  spellCheck
                  placeholder="Start writing Markdown…"
                  aria-label="Markdown editor"
                  className="h-[45vh] w-full resize-none bg-transparent px-4 py-3 font-mono text-sm leading-relaxed outline-none md:h-auto md:flex-1"
                />
              </section>
              <section className="flex flex-col border-t border-zinc-200 md:min-h-0 md:border-t-0 dark:border-zinc-800" aria-label="Preview">
                <div className="pane-label">Preview</div>
                <div
                  className="md-preview px-4 py-3 md:flex-1 md:overflow-y-auto"
                  data-testid="preview"
                  onClick={onPreviewClick}
                  dangerouslySetInnerHTML={{ __html: previewHtml }}
                />
              </section>
            </div>
          </>
        ) : (
          <div className="grid flex-1 place-items-center p-6 text-center">
            <div>
              <p className="text-zinc-500 dark:text-zinc-400">
                {notes.length === 0 ? 'You have no notes yet.' : 'Select a note to start editing.'}
              </p>
              <button
                type="button"
                onClick={addNote}
                className="mt-3 rounded-md bg-indigo-600 px-3 py-1.5 text-sm font-medium text-white hover:bg-indigo-500"
              >
                Create a note
              </button>
              <button type="button" onClick={() => setMobileView('list')} className="mt-3 ml-2 text-sm underline md:hidden">
                Back to list
              </button>
            </div>
          </div>
        )}
      </main>

      {pendingDelete && (
        <ConfirmDialog
          title="Delete note?"
          message={`“${displayTitle(pendingDelete)}” will be permanently deleted. This can’t be undone.`}
          confirmLabel="Delete"
          onConfirm={confirmDelete}
          onCancel={() => setPendingDelete(null)}
        />
      )}
    </div>
  )
}

export interface Note {
  id: string
  title: string
  content: string
  pinned: boolean
  createdAt: number
  updatedAt: number
}

export interface AppState {
  notes: Note[]
  activeId: string | null
}

export const STORAGE_KEY = 'md-notes:v1'
export const THEME_KEY = 'md-notes:theme'

export function newId(): string {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) return crypto.randomUUID()
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`
}

export function createNote(now = Date.now(), title = '', content = ''): Note {
  return { id: newId(), title, content, pinned: false, createdAt: now, updatedAt: now }
}

export function displayTitle(note: Pick<Note, 'title'>): string {
  return note.title.trim() || 'Untitled'
}

/** Pinned notes first, then most recently edited first. */
export function sortNotes(notes: Note[]): Note[] {
  return [...notes].sort(
    (a, b) =>
      Number(b.pinned) - Number(a.pinned) || b.updatedAt - a.updatedAt || b.createdAt - a.createdAt,
  )
}

/** Case-insensitive substring search over titles and contents. */
export function searchNotes(notes: Note[], query: string): Note[] {
  const q = query.trim().toLowerCase()
  if (!q) return notes
  return notes.filter((n) => n.title.toLowerCase().includes(q) || n.content.toLowerCase().includes(q))
}

export interface Segment {
  text: string
  match: boolean
}

/** Split text into matching / non-matching segments for highlighting. */
export function highlight(text: string, query: string): Segment[] {
  const q = query.trim().toLowerCase()
  if (!q) return text ? [{ text, match: false }] : []
  const lower = text.toLowerCase()
  const out: Segment[] = []
  let pos = 0
  for (;;) {
    const idx = lower.indexOf(q, pos)
    if (idx === -1) break
    if (idx > pos) out.push({ text: text.slice(pos, idx), match: false })
    out.push({ text: text.slice(idx, idx + q.length), match: true })
    pos = idx + q.length
  }
  if (pos < text.length) out.push({ text: text.slice(pos), match: false })
  return out
}

/**
 * A one-line preview of the note body. With a query, it is centred on the
 * first match so the highlight is visible; otherwise it is the opening text.
 */
export function snippet(content: string, query = '', radius = 40): string {
  const flat = content.replace(/\s+/g, ' ').trim()
  const q = query.trim().toLowerCase()
  const idx = q ? flat.toLowerCase().indexOf(q) : -1
  if (idx === -1) return flat.slice(0, radius * 2)
  const start = Math.max(0, idx - radius)
  const end = Math.min(flat.length, idx + q.length + radius)
  return (start > 0 ? '…' : '') + flat.slice(start, end) + (end < flat.length ? '…' : '')
}

/** Counts words in the Markdown source, ignoring syntax and link URLs. */
export function wordCount(md: string): number {
  const text = md
    .replace(/^\s*(```|~~~).*$/gm, ' ') // fence lines
    .replace(/\]\([^)]*\)/g, ']') // link targets
    .replace(/^\s*(?:[-*+]|\d+[.)])\s+\[[ xX]\]/gm, ' ') // task markers
  const words = text.match(/[\p{L}\p{N}]+(?:['’.-][\p{L}\p{N}]+)*/gu)
  return words ? words.length : 0
}

export function relativeTime(ts: number, now = Date.now()): string {
  const s = Math.round((now - ts) / 1000)
  if (s < 45) return 'just now'
  const m = Math.round(s / 60)
  if (m < 60) return `${m}m ago`
  const h = Math.round(m / 60)
  if (h < 24) return `${h}h ago`
  const d = Math.round(h / 24)
  if (d < 7) return `${d}d ago`
  return new Date(ts).toLocaleDateString()
}

function isNote(v: unknown): v is Note {
  if (!v || typeof v !== 'object') return false
  const n = v as Record<string, unknown>
  return (
    typeof n.id === 'string' &&
    typeof n.title === 'string' &&
    typeof n.content === 'string' &&
    typeof n.updatedAt === 'number'
  )
}

/** Loads saved state. Returns null when nothing has been saved yet. */
export function loadState(storage: Pick<Storage, 'getItem'>): AppState | null {
  let raw: string | null
  try {
    raw = storage.getItem(STORAGE_KEY)
  } catch {
    return null
  }
  if (raw == null) return null
  try {
    const data = JSON.parse(raw) as { notes?: unknown; activeId?: unknown }
    const notes = Array.isArray(data.notes)
      ? data.notes.filter(isNote).map((n) => ({
          ...n,
          pinned: Boolean(n.pinned),
          createdAt: typeof n.createdAt === 'number' ? n.createdAt : n.updatedAt,
        }))
      : []
    const activeId =
      typeof data.activeId === 'string' && notes.some((n) => n.id === data.activeId) ? data.activeId : null
    return { notes, activeId }
  } catch {
    return { notes: [], activeId: null }
  }
}

export function saveState(storage: Pick<Storage, 'setItem'>, state: AppState): boolean {
  try {
    storage.setItem(STORAGE_KEY, JSON.stringify(state))
    return true
  } catch {
    return false
  }
}

